/*
 Problem: 3499. Maximize Active Section with Trade I
 Language: cpp
 Runtime: 83 ms (63.54%)
 Memory: 79 MB (69.01%)
 Tags: String, Enumeration
*/
class Solution {
public:
    int maxActiveSectionsAfterTrade(string s) {
        int ones = count(s.begin(), s.end(), '1');
        int ans = ones;

        s = "1" + s + "1";

        int i = 0, n = s.size();

        while (s[i] == '1') i++;

        int L = 0;
        while (i < n && s[i] == '0') L++, i++;

        while (i < n) {
            while (i < n && s[i] == '1') i++;
            if (i == n) break;

            int R = 0;
            while (i < n && s[i] == '0') R++, i++;
            if (!R) break;

            ans = max(ans, ones + L + R);
            L = R;
        }

        return ans;
    }
};
